import{_ as l,l as i,o as e,c as s,v as o,p as n,x as t,d,i as B,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"大对象存储","description":"","frontmatter":{"title":"大对象存储","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blob-storage.md","filePath":"cs/blob-storage.md","lastUpdated":1789023840000}'),c={name:"cs/blob-storage.md"};function E(A,a,h,L,_,O){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="大对象存储" tabindex="-1">大对象存储 <a class="header-anchor" href="#大对象存储" aria-label="Permalink to &quot;大对象存储&quot;">​</a></h1><div class="epigraph"><p>大对象不进普通行槽：流式读写、单独 WAL 策略、可选外置文件，避免一次把缓冲池打成一张图片。</p><footer>—— 据 SQL BLOB/CLOB；Stonebraker 等对大对象；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/varlen-overflow">上一课</a>把中等变长放进溢出链。本课不跟转发 RID。缺口是 MB–GB 级值：若当超长 VARCHAR，VACUUM、复制、统计、一次 <code>SELECT *</code> 都会灾难。大对象（LOB）是另一存储主键：oid 在行上，字节在侧表或文件系统，API 是分段读写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>事务：LOB 写入要原子可见，崩溃要回滚未提交字节。若外置文件不进 WAL，就要另做强制与垃圾回收。缺口是<strong>与行同一 ACID 还是最终一致外链</strong>。应用把图片 URL 放进对象存储、库内只留键，是常见切分——那是应用设计，库仍可能提供内置 LOB。</p><p>复制：物理复制会把 LOB 页也传；逻辑复制可能跳过或切片。CDC 后课。查询优化：不要把 LOB 列拖进哈希表当连接键。</p><p><span class="marginnote">SQL 标准 BLOB/CLOB。PostgreSQL large object 与 TOAST 阈值分工。本课不把对象存储网关当数据库内核必做，但点名外置是合法边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行内存 LOB 定位符。读：<code>read(offset, len)</code> 填缓冲，不一次性物化。写：追加或覆盖段，日志按段。GC：删除行后回收 LOB 页，与 MVCC 可见性对齐——未结束快照仍可能读旧字节。</p><p>索引：通常不直接索全文，可对校验或元数据列索引；全文倒排对 CLOB 要分词管道。</p>',10)),(e(),n(p,null,{default:t(()=>[B(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROW%5B%22%E8%A1%8C%E4%B8%8A%20LOB%20%E5%BC%95%E7%94%A8%22%5D%20--%3E%20SEG%5B%22%E6%AE%B5%E9%A1%B5%E6%88%96%E4%BE%A7%E8%A1%A8%22%5D%0A%20%20SEG%20--%3E%20API%5B%22%E6%B5%81%E5%BC%8F%E8%AF%BB%20%2F%20%E5%86%99%22%5D%0A%20%20API%20--%3E%20WAL%5B%22%E6%8C%89%E6%AE%B5%E6%97%A5%E5%BF%97%22%5D%0A%20%20ROW%20--%3E%20EXT%5B%22%E6%88%96%E5%A4%96%E7%BD%AE%E5%AF%B9%E8%B1%A1%E9%94%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓冲池：LOB 段用一次性访问模式，替换应像扫描。pin 泄漏一张 1GB 对象会冻死池。压缩：段级压缩，随机偏移要可寻址或放弃跨段解压。</p><p>安全：权限在行级还是 LOB oid 级，漏洞常出在「知道 oid 就能读」。行级安全后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲表分区键如何包含 LOB。也不把向量嵌入当 BLOB 教程——向量库后课有自己的 ANN 文件。透明加密可盖 LOB 段。</p><p>后课默认：大值走 LOB 或外置，行上只留引用。表分区：水平切行集合，控制扫描与维护窗口。</p><p>一次 <code>SELECT *</code> 拉出所有 LOB 是接口设计错误，不是优化器无能。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LOB 流式分段，行上存引用；WAL/GC 必须覆盖段。</li><li>外置对象存储把一致性边界外移。</li><li>表分区下一课：按键水平切表。</li><li>出处：SQL LOB；Ramakrishnan and Gehrke；TOAST/large object 实践。</li></ul>',9))])}const C=l(c,[["render",E]]);export{b as __pageData,C as default};
